properties.$st-css:
:import{
    -st-from: 'wix-ui-santa/index.st.css';
    -st-named: StylableButton
}
.root{
    -st-extends: StylableButton;
    transition: all 0.2s ease, visibility 0s;
    padding: 3px;
    box-shadow:;
    /*inset 3.54px 3.54px 0 -64px value(site_1_1)*/ border: 4px double value(site_1_1); background: #B4BBAC
}
.root:hover{
    background: value(site_1_1);
    border: 3px double rgb(11, 47, 91)
}
.root:hover::label{
    color: value(site_1_5)
}
.root:disabled{
    background: #E2E2E2
}
.root:disabled::label{
    color: #8F8F8F
}
.root:disabled::icon{
    fill: #8F8F8F
}
.root::container{
    transition: inherit
}
.root::label{
    transition: inherit;
    color: value(site_1_1);
    font-weight: normal;
    font-style: normal;
    font-family: "playfair display",serif;
    font-size: 17px;
    display: initial;
    letter-spacing: 0.15em
}
.root::icon{
    transition: inherit;
    width: 10px;
    height: 10px;
    fill: value(site_1_1);
    display: none
}
.root:hover::icon{
    fill: value(site_1_5)
}
@media value(mobileMediaQuery) {
    .root::label {
        font-size: 11px;
    }
}

